import 'package:flutter/material.dart';
import 'package:flutter_widget_from_html/flutter_widget_from_html.dart';
import 'package:url_launcher/url_launcher.dart';
import '../constants/app_colors.dart';

/// Renders HTML generated by WYSIWYG editors (like ReactQuill in the Admin panel)
/// with seamless typography, link handling, image styling, and Quill-specific classes.
class AppHtmlView extends StatelessWidget {
  final String? html;
  final TextStyle? baseTextStyle;
  final String? fallbackText;

  const AppHtmlView({
    super.key,
    required this.html,
    this.baseTextStyle,
    this.fallbackText,
  });

  /// Check whether the provided HTML string is effectively empty or contains only blank tags.
  bool _isEffectivelyEmpty(String? raw) {
    if (raw == null || raw.trim().isEmpty) return true;
    final stripped = raw.replaceAll(RegExp(r'<[^>]*>'), '').trim();
    // Also check for embedded images; if there are img tags, it's not empty even if no text
    final hasImages = raw.contains('<img');
    return stripped.isEmpty && !hasImages;
  }

  /// Normalize content: if it is plain text without HTML tags, convert newlines to <br>
  String _normalizeHtml(String raw) {
    final trimmed = raw.trim();
    final hasTags = RegExp(r'<[a-z/][\s\S]*>', caseSensitive: false).hasMatch(trimmed);
    if (!hasTags) {
      // Plain text: escape angle brackets & convert newlines
      final escaped = trimmed
          .replaceAll('&', '&amp;')
          .replaceAll('<', '&lt;')
          .replaceAll('>', '&gt;')
          .replaceAll('\n', '<br/>');
      return '<p>$escaped</p>';
    }
    return trimmed;
  }

  @override
  Widget build(BuildContext context) {
    if (_isEffectivelyEmpty(html)) {
      if (fallbackText != null && fallbackText!.isNotEmpty) {
        return Text(
          fallbackText!,
          style: const TextStyle(
            color: AppColors.textMedium,
            fontSize: 14,
            height: 1.5,
          ),
        );
      }
      return const SizedBox.shrink();
    }

    final normalized = _normalizeHtml(html!);

    return HtmlWidget(
      normalized,
      textStyle: baseTextStyle ??
          const TextStyle(
            fontSize: 15,
            height: 1.6,
            color: AppColors.textDark,
          ),
      customStylesBuilder: (element) {
        // Quill alignment classes
        if (element.classes.contains('ql-align-center')) {
          return {'text-align': 'center'};
        }
        if (element.classes.contains('ql-align-right')) {
          return {'text-align': 'right'};
        }
        if (element.classes.contains('ql-align-justify')) {
          return {'text-align': 'justify'};
        }

        // Quill size classes
        if (element.classes.contains('ql-size-small')) {
          return {'font-size': '12px'};
        }
        if (element.classes.contains('ql-size-large')) {
          return {'font-size': '19px', 'font-weight': '600'};
        }
        if (element.classes.contains('ql-size-huge')) {
          return {'font-size': '24px', 'font-weight': 'bold'};
        }

        // Quill syntax/code blocks
        if (element.classes.contains('ql-syntax')) {
          return {
            'background-color': '#F3ECD9',
            'border-radius': '8px',
            'padding': '10px 14px',
            'font-family': 'monospace',
            'color': '#3D3D3D',
            'display': 'block',
            'margin': '8px 0',
          };
        }

        // Element-level typography & styling
        switch (element.localName) {
          case 'a':
            return {
              'color': '#3C4FAF',
              'text-decoration': 'underline',
              'font-weight': '600',
            };
          case 'blockquote':
            return {
              'border-left': '3px solid #3C4FAF',
              'padding-left': '12px',
              'color': '#6B6B6B',
              'font-style': 'italic',
              'margin': '10px 0',
            };
          case 'h1':
            return {
              'font-size': '22px',
              'font-weight': 'bold',
              'color': '#3D3D3D',
              'margin-top': '16px',
              'margin-bottom': '8px',
              'line-height': '1.3',
            };
          case 'h2':
            return {
              'font-size': '18px',
              'font-weight': 'bold',
              'color': '#3D3D3D',
              'margin-top': '14px',
              'margin-bottom': '6px',
              'line-height': '1.3',
            };
          case 'h3':
            return {
              'font-size': '16px',
              'font-weight': '600',
              'color': '#3D3D3D',
              'margin-top': '12px',
              'margin-bottom': '4px',
              'line-height': '1.3',
            };
          case 'p':
            return {
              'margin-top': '0',
              'margin-bottom': '8px',
              'line-height': '1.6',
            };
          case 'ul':
          case 'ol':
            return {
              'margin-top': '4px',
              'margin-bottom': '8px',
              'padding-left': '20px',
            };
          case 'li':
            return {
              'margin-bottom': '4px',
              'line-height': '1.5',
            };
          case 'img':
            return {
              'border-radius': '12px',
              'max-width': '100%',
              'margin': '10px 0',
            };
          case 'code':
            return {
              'background-color': '#F3ECD9',
              'padding': '2px 6px',
              'border-radius': '4px',
              'font-family': 'monospace',
              'font-size': '13px',
            };
          case 'hr':
            return {
              'border-top': '1px solid #E5DDD0',
              'margin': '16px 0',
            };
        }

        return null;
      },
      onTapUrl: (url) async {
        final uri = Uri.tryParse(url);
        if (uri != null && await canLaunchUrl(uri)) {
          await launchUrl(uri, mode: LaunchMode.externalApplication);
          return true;
        }
        return false;
      },
    );
  }
}
